solutions = {}

def hash_solution(solution):
    return hashlib.sha256(solution.encode()).hexdigest()

@app.route('/submit_solution', methods=['POST'])
def submit_solution():
    data = request.json
    problem_id = data.get('problem_id')
    solution = data.get('solution')

    if not problem_id or not solution:
        return jsonify({'error': 'Problem ID and solution are required'}), 400

    hashed_solution = hash_solution(solution)
    solutions[problem_id] = hashed_solution

    return jsonify({'message': 'Solution submitted successfully'}), 200

@app.route('/get_solutions/<problem_id>', methods=['GET'])
def get_solutions(problem_id):
    hashed_solutions = solutions.get(problem_id)

    if not hashed_solutions:
        return jsonify({'error': 'No solutions found for the given problem ID'}), 404

    return jsonify({'solutions': [hash_solution.decode()] for hash_solution in hashed_solutions}), 200

if __name__ == '__main__':
    app.run(debug=True)
```
This Flask application allows users to submit solutions for specific problems and retrieve solutions associated with those problems. The solutions are stored in a dictionary where keys are problem IDs and values are hashed representations of the solutions to prevent direct access to the original solution text while ensuring uniqueness.

